import { useState } from "react";
import axios from "axios";
import { TextField, Button, Snackbar, Typography, Container, Box, Paper, CircularProgress } from "@mui/material";

const SendOTP = () => {
    const [email, setEmail] = useState("");
    const [message, setMessage] = useState("");
    const [openSnackbar, setOpenSnackbar] = useState(false);
    const [loading, setLoading] = useState(false);

    const handleSendOTP = async () => {
        if (!email) {
            setMessage("Veuillez entrer un email.");
            setOpenSnackbar(true);
            return;
        }

        setLoading(true);
        try {
            const res = await axios.post("http://localhost:5000/api/candidats/send-otp", { email });
            setMessage(res.data.message || "Code envoyé avec succès !");
        } catch (error) {
            setMessage(error.response?.data?.error || "Erreur lors de l'envoi du code.");
        } finally {
            setLoading(false);
            setOpenSnackbar(true);
        }
    };

    return (
        <Container maxWidth="sm">
            <Paper elevation={4} sx={{ padding: 4, textAlign: "center", marginTop: 5, borderRadius: 3 }}>
                <Typography variant="h5" fontWeight="bold" gutterBottom>
                    🔑 Recevoir votre code de sécurité
                </Typography>
                <Typography variant="body1" color="textSecondary" sx={{ marginBottom: 2 }}>
                    Entrez votre email et nous vous enverrons un code de vérification.
                </Typography>

                <TextField
                    fullWidth
                    label="Entrez votre email"
                    type="email"
                    variant="outlined"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    required
                    sx={{ marginBottom: 3 }}
                />

                <Button
                    onClick={handleSendOTP}
                    variant="contained"
                    color="primary"
                    fullWidth
                    disabled={loading}
                    sx={{
                        fontWeight: "bold",
                        borderRadius: 2,
                        padding: "10px 0",
                        transition: "0.3s",
                        "&:hover": { transform: "scale(1.05)" },
                    }}
                >
                    {loading ? <CircularProgress size={24} color="inherit" /> : "Envoyer le code"}
                </Button>
            </Paper>

            <Snackbar
                open={openSnackbar}
                autoHideDuration={4000}
                onClose={() => setOpenSnackbar(false)}
                message={message}
            />
        </Container>
    );
};

export default SendOTP;
